   108	function parseBrowserFlags(args: string[]): BrowserCliFlags {
   109	  const flags: BrowserCliFlags = { _: [], json: false, keepImages: false };
   110	  const stringFlags: Record<string, keyof BrowserCliFlags> = {
   111	    host: "host",
   112	    "corporate-ca": "corporateCa",
   113	    "corporate-ca-keychain-label": "corporateCaKeychainLabel",
   114	    "corporate-ca-keychain": "corporateCaKeychain",
   115	    "network-mode": "networkMode",
   116	    image: "image",
   117	  };
   118	  for (let index = 0; index < args.length; index += 1) {
   119	    const arg = args[index]!;
   120	    if (!arg.startsWith("--")) {
   121	      flags._.push(arg);
   122	      continue;
   123	    }
   124	    if (arg === "--json") {
   125	      flags.json = true;
   126	      continue;
   127	    }
   128	    if (arg === "--keep-images") {
   129	      flags.keepImages = true;
   130	      continue;
   131	    }
   132	    const target = stringFlags[arg.slice(2)];
   133	    if (!target) throw cliError(`Unknown browser flag ${arg}.`);
   134	    const value = args[index + 1];
   135	    if (!value || value.startsWith("--")) throw cliError(`Missing value for ${arg}.`);
   136	    (flags as Record<string, unknown>)[target] = value;
   137	    index += 1;
   138	  }
   139	  return flags;
   140	}
