   554	export async function runBrowserCli(args: string[], dependencies: BrowserCliDependencies): Promise<number> {
   555	  const flags = parseBrowserFlags(args);
   556	  const write = dependencies.stdout ?? ((value: string) => process.stdout.write(value));
   557	  const anvilHome = resolve(dependencies.anvilHome ?? join(dependencies.homeDir ?? homedir(), ".anvil"));
   558	  const command = flags._[0];
   559	  if (!command || command === "help") {
   560	    write(`${browserCliUsage()}\n`);
